from pathlib import Path
import re

root=Path(__file__).parent/'review'
base=(root/'ognetushiteli'/'index.html').read_text(encoding='utf-8')
extinguisher_runtime=(Path(__file__).parent/'extinguisher-pages.js').read_text(encoding='utf-8')

def write(path, pairs):
    text=base
    for old,new in pairs.items(): text=text.replace(old,new)
    (root/path/'index.html').write_text(text,encoding='utf-8')

