for page in (Path('ognetushiteli'), Path('kalkulyatory')/'ognetushiteli'):
    target = root/page/'index.html'
    text = target.read_text(encoding='utf-8')
    text = re.sub(r'<script src="(?:/|(?:\.\./)+)extinguisher-pages\.js\?v=\d+"></script>', '', text)
    text = re.sub(r"<script>\s*\(\(\) => \{\s*const root = document\.getElementById\('pz-ognetushiteli-page'\);.*?\n\}\)\(\);\s*</script>", '', text, flags=re.S)
    text = re.sub(r'<!-- extinguisher-runtime:(?:start|end) -->', '', text)
    text = text.replace('</body>', f'<!-- extinguisher-runtime:start --><script>\n{extinguisher_runtime}\n</script><!-- extinguisher-runtime:end --></body>')
    target.write_text(text, encoding='utf-8')
print('Built remaining stage 2 pages')
